/* الدروس — كل الأرقام في الأمثلة افتراضية للتوضيح ومكتوب افتراضاتها.
   {{ID}} = رقم مرجع من السجل المركزي (refs.js) — لا يُضاف مرجع إلا بعد فتحه والتحقق منه. */
window.BH = window.BH || {};
var CALC = function(rows){ /* جدول حساب: [البند, القيمة] ; الصف اللي يبدأ بـ = يبقى إجمالي */
  return '<div class="table-wrap"><table class="calc"><thead><tr><th>الخطوة</th><th>الحساب</th><th>النتيجة</th></tr></thead><tbody>'+rows.map(function(r){var t=r[0].charAt(0)==='=';return '<tr'+(t?' class="total"':'')+'><td>'+(t?r[0].slice(1):r[0])+'</td><td class="en" style="text-align:start">'+(r[1]||'')+'</td><td>'+r[2]+'</td></tr>'}).join('')+'</tbody></table></div>';
};
BH.lessons = [
/* ======================================================= 1 */
{id:'basics-1',n:1,level:'مبتدئ',domain:'أساسيات',updated:'2026-10-14',
title:'الادخار والاستثمار والتداول والمضاربة: إيه الفرق؟',
short:'أربع كلمات الناس بتخلط بينهم، والفرق بينهم هو أساس كل حاجة بعد كده.',
summary:'<ul><li><b>الادخار</b> = تحوّش فلوس للأمان.</li><li><b>الاستثمار</b> = تشتري أصل حقيقي وتستفيد من نشاطه على مدة طويلة.</li><li><b>التداول</b> = بيع وشرا كتير في مدة قصيرة عشان فرق السعر.</li><li><b>المضاربة (بالمعنى المالي)</b> = تداول بمخاطرة عالية على تغيّر السعر.</li></ul><p>كل ما المدة تقصر والمخاطرة تزيد، كل ما الاحتمال إنك تخسر يزيد، وكل ما الأسئلة الشرعية تكتر.</p>',
body:'<ol class="steps"><li><b>ابدأ بالادخار.</b> قبل أي استثمار، لازم يكون معاك [[saving|صندوق طوارئ]] يكفي 3–6 شهور مصاريف. الفلوس دي ماتدخلش بيها أي مخاطرة.</li><li><b>الاستثمار</b> معناه إنك بتملك حاجة بتشتغل: حصة في شركة ([[stock|سهم]])، وحدة في [[fund|صندوق]]، [[sukuk|صك]]. الربح بييجي من <b>نشاط حقيقي</b>: الشركة بتبيع وتكسب.</li><li><b>التداول</b> بيركز على <b>حركة السعر</b> مش على الشركة. إنت محتاج تبقى صح في التوقيت كمان، مش بس في الاختيار.</li><li><b>المضاربة</b> بالمعنى المالي = تداول أسرع وأخطر، وأحيانًا بفلوس مش بتاعتك ([[leverage|رافعة]]).</li><li><b>انتبه للكلمة:</b> «المضاربة» في الفقه اسم عقد شرعي مختلف تمامًا: واحد بالمال وواحد بالجهد والربح بينهم ([[mudaraba|عقد المضاربة]]).</li></ol>'+
'<div class="flow"><span class="node">ادخار<br><small>أمان</small></span><span class="arr">‹</span><span class="node">استثمار<br><small>سنين</small></span><span class="arr">‹</span><span class="node">تداول<br><small>أيام/ساعات</small></span><span class="arr">‹</span><span class="node hl">مضاربة بالرافعة<br><small>دقايق — أعلى خطر</small></span></div>',
examples:[{title:'مثال: 3 أشخاص ومع كل واحد 50,000 جنيه',kind:'hypothetical',open:true,html:
'<ul><li><b>أحمد (ادخار):</b> حط 50,000 في مكان آمن. بعد سنة لسه 50,000 (أو أكتر شوية لو في وعاء بعائد). القيمة الشرائية ممكن تقل بسبب التضخم.</li><li><b>منى (استثمار):</b> اشترت أسهم 5 شركات نشاطها مباح × 10,000. بعد سنة: شركتين طلعوا 20%، واحدة نزلت 30%، اتنين ثابتين. الحساب تحت.</li><li><b>كريم (تداول):</b> عمل 60 صفقة في السنة. حتى لو كسب في نص الصفقات، الرسوم لوحدها ممكن تاكل جزء كبير (شوف درس الرسوم).</li></ul>'+
CALC([['شركة 1 (+20%)','10,000 × 1.20','12,000'],['شركة 2 (+20%)','10,000 × 1.20','12,000'],['شركة 3 (−30%)','10,000 × 0.70','7,000'],['شركة 4 و5 (ثابتين)','10,000 × 2','20,000'],['=قيمة محفظة منى بعد سنة','12,000+12,000+7,000+20,000','51,000 (+2%) قبل الرسوم']])+
'<p>لاحظ: التنويع منع إن خسارة شركة 3 (30%) تبقى خسارة على كل الفلوس.</p>'}],
shariah:'<p>الشرع ما حرّمش الربح من البيع والشرا وتغير الأسعار؛ قال تعالى: ﴿وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا﴾ {{F68}}. المشكلة مش في كلمة «تداول» ولا «مضاربة»، المشكلة في <b>طبيعة العقد</b>:</p><ul><li>هل بتشتري حاجة حقيقية وتملكها؟</li><li>هل فيه قرض بفايدة (ربا)؟</li><li>هل فيه جهالة كبيرة ([[gharar|غرر]]) أو مراهنة ([[maysir|ميسر]])؟</li><li>هل نشاط الأصل نفسه مباح؟</li></ul>',
risks:'<ul><li>تبدأ تستثمر قبل ما يكون معاك صندوق طوارئ.</li><li>تفتكر «التداول» و«الاستثمار» حاجة واحدة.</li><li>تسأل «التداول حلال ولا حرام؟» — السؤال ده ملوش إجابة واحدة؛ لازم تحدد: تداول إيه؟ بأي عقد؟ بفلوس مين؟</li></ul>',
checklist:['معايا صندوق طوارئ منفصل؟','الفلوس دي أقدر أسيبها سنين ومحتاجهاش؟','أنا ناوي أستثمر (أملك وأستنى) ولا أتداول (أبيع وأشتري كتير)؟','فاهم الأصل اللي هشتريه بيكسب منين؟'],
todo:['اكتب في ملاحظاتك: كام شهر مصاريف عندك محوّشين؟','لما تشوف رسالة في أي قناة، اسأل: دي بتتكلم عن استثمار ولا تداول ولا مضاربة؟','كمّل الدرس 2 عشان تفهم السعر بيتحرك ليه.'],
known:['الفرق بين المفاهيم الأربعة.','إن طبيعة العقد هي اللي بتحدد الحكم، مش الاسم.'],
unknown:['مدى مناسبة أي نوع ليك شخصيًا — ده بيعتمد على ظروفك وده مش دور الموقع.'],
quiz:[
{q:'سارة بتشتري أسهم شركة وناوية تفضل فيها 7 سنين وتستفيد من أرباحها. ده اسمه إيه؟',opts:['تداول','استثمار','مضاربة بالرافعة'],a:1,why:'مدة طويلة واهتمام بالشركة نفسها = استثمار.'},
{q:'سؤال «التداول حلال ولا حرام؟» إجابته إيه؟',opts:['حلال دايمًا','حرام دايمًا','يعتمد على نوع التداول والعقد وطريقة التمويل'],a:2,why:'تداول سهم حقيقي مملوك بفلوسك غير CFD برافعة بقرض. لازم تحدد الصورة.'},
{q:'إيه أول خطوة قبل أي استثمار؟',opts:['أشترك في قناة توصيات','أعمل صندوق طوارئ','أفتح حساب فوركس'],a:1,why:'من غير صندوق طوارئ ممكن تضطر تبيع في أسوأ وقت.'}]},

/* ======================================================= 2 */
{id:'market-2',n:2,level:'مبتدئ',domain:'أساسيات',updated:'2026-10-14',
title:'السوق بيشتغل إزاي؟ الربح والخسارة جايين منين؟',
short:'مين بيشتري ومين بيبيع، والسعر بيطلع وينزل ليه، والفرق بين السعر والقيمة.',
summary:'<p>السعر في البورصة = آخر سعر اتفق عليه <b>مشتري وبايع</b>. لو المشترين أكتر وأشد رغبة → السعر يطلع. لو البايعين أكتر → ينزل. الأخبار والأرباح والخوف والطمع بيحركوا ده.</p><p>ربح المستثمر بييجي من حاجتين: <b>نمو الشركة الحقيقي</b> (أرباح وتوزيعات)، أو <b>إن حد يشتري منك بسعر أعلى</b>.</p>',
body:'<ol class="steps"><li><b>كل صفقة ليها طرفين.</b> لما إنت تشتري 100 سهم، فيه حد تاني باعهم لك. ولا واحد فيكم متأكد مين اللي صح.</li><li><b>العرض والطلب:</b> تخيل 10 أشخاص عايزين يشتروا وواحد بس عايز يبيع → المشترين هيعلّوا السعر.</li><li><b>الأخبار:</b> الشركة أعلنت أرباح أعلى من المتوقع → ناس أكتر عايزة تشتري → السعر يطلع. خبر وحش → العكس.</li><li><b>[[liquidity|السيولة]]:</b> في سهم عليه تداول كبير، تقدر تبيع بسرعة. في سهم مهجور، ممكن متلاقيش مشتري غير بسعر أقل بكتير.</li><li><b>السعر ≠ القيمة:</b> [[intrinsic|السعر]] هو اللي الناس بتدفعه دلوقتي. «القيمة العادلة» تقدير — محللين مختلفين بيدوا أرقام مختلفة.</li><li><b>الاستثمار مش لعبة صفرية بالكامل:</b> لو الشركة كبرت وكسبت، المساهمين كلهم بيستفيدوا. لكن <b>التداول القصير</b> أقرب للعبة صفرية: مكسبك غالبًا خسارة حد تاني (وبعد الرسوم يبقى المجموع سالب).</li></ol>',
examples:[{title:'مثال: دفتر الأوامر بشكل مبسط',kind:'hypothetical',open:true,html:'<p>ده شكل مبسط لطلبات سهم «ألف» في لحظة:</p><div class="table-wrap"><table><thead><tr><th>عروض البيع (Ask)</th><th>الكمية</th><th>طلبات الشراء (Bid)</th><th>الكمية</th></tr></thead><tbody><tr><td>10.10</td><td>2,000</td><td>10.00</td><td>1,500</td></tr><tr><td>10.05</td><td>500</td><td>9.95</td><td>3,000</td></tr></tbody></table></div><p>لو جه حد عايز يشتري 1,000 سهم «بسعر السوق»: هياخد 500 بـ 10.05 و500 بـ 10.10 → متوسط 10.075. وكده آخر سعر اتنفذ بقى 10.10 — يعني «السهم طلع» لمجرد إن مشتري واحد مستعجل دخل.</p><p><b>الدرس:</b> في الأسهم الصغيرة، شوية فلوس قليلة ممكن تحرك السعر — ودي الفكرة اللي بيستغلها اللي بيعملوا [[pumpdump|النفخ ثم البيع]].</p>'}],
shariah:'<p>تغير السعر في حد ذاته مش مشكلة شرعية: التاجر بيشتري بسعر ويبيع بسعر أعلى. المهم إن البيع يكون على <b>شيء مملوك حقيقي</b>، من غير غش أو تلاعب. والتلاعب بالأسعار والترويج الكاذب حرام وممنوع قانونًا كمان (غش وأكل أموال الناس بالباطل).</p>',
risks:'<ul><li>تفتكر إن السعر لازم «يرجع» لأنه كان أعلى قبل كده.</li><li>تصدق «القيمة العادلة 50 جنيه» كأنها وعد.</li><li>تشتري سهم ضعيف السيولة ومتعرفش تخرج.</li></ul>',
todo:['افتح أي سهم في تطبيق رسمي وبص على الفرق بين Bid و Ask.','لما حد يقول «السهم هيطلع لـ X»، افتكر إن ده رأي، واسأل: على أي أساس؟'],
known:['السعر نتيجة عرض وطلب.','التداول القصير بعد الرسوم مجموعه سالب للمشاركين ككل.'],
unknown:['اتجاه أي سهم في المستقبل — محدش يعرفه بيقين.'],
quiz:[
{q:'السهم طلع النهارده 5%. ده معناه إيه بالضرورة؟',opts:['الشركة بقت أحسن 5%','آخر صفقات اتنفذت بسعر أعلى — والسبب ممكن يكون أي حاجة','السهم هيكمل طلوع بكرة'],a:1,why:'حركة السعر بتعكس المشترين والبايعين في اللحظة، مش بالضرورة تغير حقيقي في الشركة.'},
{q:'مين اللي باع لك السهم لما اشتريته؟',opts:['الشركة نفسها دايمًا','مستثمر تاني شايف إن البيع أحسن له دلوقتي','البورصة'],a:1,why:'في السوق الثانوي، بتشتري من مستثمر تاني. هو شايف العكس بتاعك.'},
{q:'إيه الفرق بين السعر والقيمة التقديرية؟',opts:['مفيش فرق','السعر حقيقة في اللحظة، والقيمة التقديرية رأي محلل','القيمة التقديرية دايمًا أعلى'],a:1,why:'القيمة التقديرية تقدير بيختلف من محلل لمحلل.'}]},

/* ======================================================= 3 */
{id:'assets-3',n:3,level:'مبتدئ',domain:'أساسيات',updated:'2026-10-14',
title:'خريطة الأصول: أسهم، سندات، صناديق، صكوك، عملات، سلع، عملات رقمية',
short:'بتملك إيه بالظبط في كل نوع؟ وبتكسب منين؟ وإيه السؤال الشرعي الأساسي؟',
summary:'<p>السؤال السحري لأي منتج مالي: <b>«أنا كده بملك إيه، وبكسب منين؟»</b> لو إجابتك «مش عارف» — وقف.</p>',
body:'<div class="table-wrap"><table><thead><tr><th>الأصل</th><th>بتملك إيه؟</th><th>بتكسب منين؟</th><th>المخاطرة</th><th>السؤال الشرعي الأساسي</th></tr></thead><tbody>'+
'<tr><td>[[stock|سهم]]</td><td>حصة في شركة</td><td>توزيعات + ارتفاع السعر</td><td>متوسطة–عالية</td><td>نشاط الشركة؟ ديونها وفوايدها؟</td></tr>'+
'<tr><td>[[bond|سند]] / [[tbill|أذون]]</td><td>دين على جهة</td><td>فايدة ثابتة</td><td>منخفضة–متوسطة</td><td>قرض بزيادة مشروطة = ربا</td></tr>'+
'<tr><td>[[fund|صندوق]]</td><td>وثائق في وعاء مشترك</td><td>نتيجة استثمارات الصندوق</td><td>حسب نوع الصندوق</td><td>بيستثمر في إيه فعلًا؟</td></tr>'+
'<tr><td>[[sukuk|صكوك]]</td><td>حصة في أصل/مشروع</td><td>إيجار أو ربح الأصل</td><td>متوسطة</td><td>التملك الحقيقي وعدم ضمان رأس المال</td></tr>'+
'<tr><td>عملات (صرافة)</td><td>العملة نفسها</td><td>فرق سعر الصرف</td><td>متوسطة</td><td>التقابض الفوري</td></tr>'+
'<tr><td>ذهب حقيقي</td><td>الذهب</td><td>ارتفاع السعر</td><td>متوسطة</td><td>التقابض (الذهب بالنقود يدًا بيد)</td></tr>'+
'<tr><td>[[crypto|عملة رقمية]]</td><td>رصيد رقمي على شبكة</td><td>ارتفاع السعر (غالبًا)</td><td>عالية جدًا</td><td>محل خلاف وبحث + قيود قانونية في مصر</td></tr>'+
'<tr><td>[[cfd|CFD]] / [[futures|مستقبليات]]</td><td>عقد على السعر فقط</td><td>فرق السعر</td><td>عالية جدًا</td><td>لا تملك ولا قبض + رافعة</td></tr></tbody></table></div>',
examples:[{title:'مثال: نفس الـ 10,000 جنيه بأربع طرق',kind:'hypothetical',open:true,html:'<ul><li><b>سهم:</b> اشتريت 200 سهم × 50. إنت شريك صغير في الشركة.</li><li><b>سند:</b> سلّفت جهة 10,000 بفايدة. إنت دائن، مش شريك.</li><li><b>صك إجارة:</b> تملك جزء من أصل مؤجّر، ونصيبك من الإيجار.</li><li><b>CFD على نفس السهم:</b> مابتملكش ولا سهم. عندك عقد مع منصة على فرق السعر.</li></ul><p>الأربعة ممكن يتعرضوا عليك بنفس الكلمة: «استثمر في الشركة الفلانية»! الفرق في العقد.</p>'}],
shariah:'<p>الأصل في المعاملات الإباحة إلا ما دل الدليل على منعه. الموانع الأساسية: [[riba|الربا]] {{F68}}، [[gharar|الغرر]] {{F72}}، [[maysir|الميسر]] {{F69}}، بيع ما لا تملك {{F74}}، والتعامل في نشاط محرم. التفاصيل في <a href="#/shariah">المرجع الشرعي</a> و<a href="#/products">تقييم المنتجات</a>.</p>',
risks:'<ul><li>منصة تقولك «اشتري سهم أبل» وإنت في الحقيقة بتشتري CFD.</li><li>صندوق اسمه «آمن» أو «دخل ثابت» وهو بيستثمر في أذون خزانة.</li></ul>',
checklist:['أعرف أنا هملك إيه بالظبط؟','العائد جاي من نشاط حقيقي ولا من فايدة ولا من فرق سعر بس؟','فيه تمويل/قرض في الموضوع؟'],
todo:['قبل ما تقرا أي توصية، حدد نوع الأصل من الجدول ده.','افتح <a href="#/compare">صفحة المقارنات</a> وشوف «سهم حقيقي vs CFD».'],
known:['الفرق بين التملك والدين والعقد على السعر.'],unknown:['حكم منتج معيّن عند شركة معيّنة — محتاج تقرا عقده.'],
quiz:[
{q:'لو اشتريت سند، إنت بالنسبة للشركة:',opts:['شريك','دائن (مسلّفها)','موظف'],a:1,why:'السند دين؛ إنت سلّفت الجهة.'},
{q:'في عقد CFD على سهم، إنت بتملك:',opts:['السهم','عقد على فرق سعر السهم بس','نص السهم'],a:1,why:'CFD ما بيديكش ملكية السهم.'},
{q:'«الأصل في المعاملات...»',opts:['التحريم إلا بدليل','الإباحة إلا ما دل الدليل على منعه','الكراهة'],a:1,why:'قاعدة معروفة عند جمهور الفقهاء في المعاملات.'}]},

/* ======================================================= 4 */
{id:'risk-4',n:4,level:'مبتدئ',domain:'أساسيات',updated:'2026-10-14',
title:'العائد والمخاطرة والسيولة والتقلب — والربح المحقق وغير المحقق',
short:'ليه العائد العالي معناه غالبًا خطر عالي؟ وإمتى الربح يبقى «ربح فعلًا»؟',
summary:'<p>الربح اللي على الشاشة <b>مش ربح</b> لحد ما تبيع. والعائد العالي «المضمون» علامة تحذير مش فرصة.</p>',
body:'<ol class="steps"><li><b>[[return|العائد]]</b> = (القيمة الجديدة − اللي دفعته) ÷ اللي دفعته.</li><li><b>[[risk|المخاطرة]]</b> = احتمال إنك تخسر أو النتيجة تيجي أسوأ من المتوقع.</li><li><b>[[volatility|التقلب]]</b> = قد إيه السعر بيتنطط. التقلب العالي معناه ممكن تبقى كسبان 30% النهارده وخسران 20% بعد شهر.</li><li><b>[[realized|المحقق وغير المحقق]]:</b> طول ما إنت لسه شايل السهم، ربحك «على الورق».</li><li><b>التضخم:</b> لو فلوسك زادت 10% والأسعار زادت 25%، إنت فعليًا قدرتك الشرائية قلّت.</li></ol>',
examples:[{title:'مثال: 10 أسهم بسعر 100 جنيه',kind:'hypothetical',open:true,html:CALC([['إجمالي المدفوع','10 × 100','1,000 جنيه'],['لو السعر بقى 120','10 × 120','1,200 جنيه'],['=الربح غير المحقق','1,200 − 1,000','+200 (+20%)'],['لو السعر بقى 80','10 × 80','800 جنيه'],['=الخسارة غير المحققة','800 − 1,000','−200 (−20%)']])+'<p>الحساب ده <b>قبل الرسوم</b> — شوف الدرس الجاي. ولاحظ: ارتفاع السعر مش مضمون، والمثال الحسابي <b>مش معناه</b> إن السهم ده مناسب ليك أو متوافق شرعيًا.</p>'},
{title:'مثال: التضخم والعائد الحقيقي',kind:'hypothetical',html:CALC([['فلوسك أول السنة','100,000'],['عائد 15%','100,000 × 1.15','115,000'],['التضخم 25% (افتراض)','الحاجة اللي كانت بـ 100,000 بقت بـ 125,000'],['=القدرة الشرائية الحقيقية','115,000 ÷ 1.25','92,000 (−8%)']])+'<p>العائد الحقيقي التقريبي = (1.15 ÷ 1.25) − 1 ≈ −8%.</p>'}],
shariah:'<p>تحمّل المخاطرة جزء من الربح الحلال: «الخراج بالضمان» و«الغُنم بالغُرم» — اللي بيستحق الربح هو اللي بيتحمل الخسارة. علشان كده <b>ضمان رأس المال أو ربح ثابت</b> في عقود المشاركة والمضاربة مخالف لطبيعة العقد {{F22,F23}}.</p>',
risks:'<ul><li>تحكي لنفسك إنك «كسبان» وإنت لسه مابعتش.</li><li>تصدق عرض «20% شهريًا مضمون».</li><li>تقارن عائدك بالصفر بدل ما تقارنه بالتضخم.</li></ul>',
todo:['احسب عائد أي استثمار قديم ليك بنفس الجدول.','لو حد عرض عليك عائد مضمون عالي، روح <a href="#/cases">للحالات الحقيقية</a> واقرا قصة مادوف.'],
known:['معادلة العائد.','الفرق بين المحقق وغير المحقق.'],unknown:['معدل التضخم المستقبلي.'],
quiz:[
{q:'اشتريت بـ 2,000 والقيمة دلوقتي 2,500 ولسه مابعتش. ده:',opts:['ربح محقق 500','ربح غير محقق 500','خسارة'],a:1,why:'طول ما مابعتش، الربح على الورق.'},
{q:'عائد 50% في السنة «مضمون» ده:',opts:['فرصة نادرة لازم ألحقها','علامة تحذير قوية','طبيعي في البورصة'],a:1,why:'العائد العالي والمضمون مع بعض من أشهر علامات الاحتيال.'},
{q:'لو فلوسك زادت 10% والتضخم 10%، قدرتك الشرائية:',opts:['زادت 10%','ثابتة تقريبًا','زادت 20%'],a:1,why:'الزيادة اتلغت بارتفاع الأسعار.'}]},

/* ======================================================= 5 */
{id:'fees-5',n:5,level:'مبتدئ',domain:'الرسوم',updated:'2026-10-14',
title:'الرسوم والعمولات والضرائب: العدو الصامت',
short:'إزاي مصاريف صغيرة على كل عملية تاكل ربحك — خصوصًا لو بتتداول كتير.',
summary:'<p>كل عملية شرا أو بيع ليها مصاريف: عمولة السمسار + رسوم البورصة والجهات الرقابية والإيداع المركزي + أحيانًا ضرايب، + [[spread|فرق سعر البيع والشراء]]. كل ما تتداول أكتر، كل ما تدفع أكتر.</p>',
body:'<ol class="steps"><li>اسأل السمسار عن <b>جدول العمولات الكامل</b> مكتوب.</li><li>احسب الرسوم <b>مرتين</b>: في الشرا وفي البيع.</li><li>اسأل عن الضرايب المطبقة وقت التداول (بتتغير بقرارات، فاتأكد من آخر وضع رسمي) {{E39}}.</li><li>الصفقات الصغيرة جدًا بتبقى الرسوم الثابتة فيها نسبة كبيرة.</li></ol>'+'<div class="callout warn"><div><b class="t">مهم</b>النسب في الأمثلة هنا <b>افتراضات للتوضيح</b>. النسب الفعلية في البورصة المصرية بتختلف حسب السمسار وبتتغير — راجعها من مصدر رسمي قبل أي حساب حقيقي. فيه مثال بأرقام حقيقية مؤرخة تحت.</div></div>',
examples:[{title:'مثال: 10 أسهم × 100 جنيه بعد الرسوم',kind:'hypothetical',open:true,html:'<p><b>الافتراض:</b> إجمالي الرسوم 0.5% من قيمة كل عملية (شرا أو بيع)، ومفيش ضرايب في المثال.</p>'+CALC([['قيمة الشراء','10 × 100','1,000'],['رسوم الشراء','1,000 × 0.5%','5'],['=التكلفة الكلية','1,000 + 5','1,005'],['البيع عند 120','10 × 120','1,200'],['رسوم البيع','1,200 × 0.5%','6'],['=صافي الربح','1,200 − 6 − 1,005','+189 (≈ 18.8%)'],['البيع عند 80','10 × 80','800'],['رسوم البيع','800 × 0.5%','4'],['=صافي الخسارة','800 − 4 − 1,005','−209 (≈ −20.8%)']])+'<p>الرسوم خلّت الربح أقل والخسارة أكبر.</p>'},
{title:'مثال حقيقي: رسوم شراء أسهم بـ 10,000 جنيه في البورصة المصرية (الأرقام بتاريخ 14 أكتوبر 2026)',kind:'hypothetical',open:true,html:'<p>الأرقام دي من جدول رسوم تطبيق سمسرة مرخص (ثاندر) {{E40}}، ورسوم البورصة بقرار رئيس الوزراء {{E38}}، وضريبة الدمغة بالقانون 153 لسنة 2026 {{E39}}. <b>شركات السمسرة التانية عمولتها مختلفة، والرسوم بتتغير</b> — راجعها وقت ما تحتاجها.</p>'+CALC([['عمولة السمسار','2 جنيه + 10,000 × 0.1%','12 جنيه'],['رسوم البورصة','10,000 × 0.01%','1 جنيه'],['رسوم مصر للمقاصة','10,000 × 0.01%','1 جنيه'],['رسوم الرقابة المالية','10,000 × 0.005%','0.5 جنيه'],['ضريبة الدمغة (0.5 في الألف)','10,000 × 0.05%','5 جنيه'],['=إجمالي رسوم الشراء','12 + 1 + 1 + 0.5 + 5','19.5 جنيه (≈ 0.2%)'],['=اللفة كاملة (شراء + بيع) تقريبًا','19.5 × 2','≈ 39 جنيه (≈ 0.4%) + فرق سعر البيع والشراء']])+'<p>وضريبة الأرباح الرأسمالية على الأسهم المقيدة اتلغت بالقانون 153 لسنة 2026 {{E39}}. لو بتشتري وتبيع في نفس الجلسة، الدمغة بتبقى 0.25 في الألف {{E39}}.</p>'},
{title:'مثال: المتداول اللي بيعمل صفقات كتير',kind:'hypothetical',html:'<p><b>الافتراض:</b> رأس مال 10,000، وكل «لفة» (شرا + بيع) بتكلف حوالي 1% من قيمة الصفقة، وبيعمل 40 لفة في السنة بكامل المبلغ.</p>'+CALC([['تكلفة اللفة الواحدة','10,000 × 1%','100'],['=تكلفة 40 لفة في السنة','100 × 40','4,000 = 40% من رأس المال']])+'<p>يعني محتاج يكسب 40% في السنة من فرق الأسعار <b>عشان بس يتعادل</b>. ده هدف صعب جدًا حتى على المحترفين.</p>'}],
shariah:'<p>العمولة مقابل خدمة السمسرة <b>جائزة</b> في الأصل لأنها أجرة على عمل. الإشكال بيظهر لما العمولة تتجمع مع <b>قرض</b> من نفس السمسار (زي الهامش) — ده موضوع درس الرافعة. {{F73}}</p>',
risks:'<ul><li>تحسب الربح من غير الرسوم.</li><li>تتداول كتير عشان «تلحق كل فرصة».</li><li>تنسى الضرايب.</li></ul>',
checklist:['معايا جدول عمولات السمسار مكتوب؟','حسبت الرسوم في الشرا والبيع؟','عارف الضرايب المطبقة حاليًا من مصدر رسمي؟'],
todo:['اطلب من أي سمسار مرخص جدول العمولات واحسب بيه المثال ده تاني.','حط في ملاحظاتك: «ربحي الحقيقي = بعد الرسوم والضرايب».'],
known:['طريقة حساب أثر الرسوم.'],unknown:['عمولة كل شركة سمسرة غير اللي في المثال — بتختلف وتتغير.'],
quiz:[
{q:'اشتريت بـ 1,000 وبعت بـ 1,050 والرسوم 0.5% في كل عملية. ربحك الصافي تقريبًا:',opts:['50','حوالي 39.75','أكتر من 50'],a:1,why:'رسوم الشرا 5 + رسوم البيع 5.25 = 10.25 → 50 − 10.25 = 39.75.'},
{q:'ليه التداول الكتير خطر حتى لو كسبت نص الصفقات؟',opts:['لأن الرسوم بتتراكم وممكن تاكل الأرباح','لأن البورصة بتمنع ده','مفيش خطر'],a:0,why:'كل لفة ليها تكلفة، ومع العدد الكبير التكلفة بتبقى ضخمة.'},
{q:'عمولة السمسار مقابل تنفيذ الأوامر:',opts:['حرام دايمًا','جائزة في الأصل كأجرة على خدمة','ربا'],a:1,why:'الأجرة على عمل جائزة؛ الإشكال لو اجتمعت مع قرض مشروط.'}]},

/* ======================================================= 6 */
{id:'orders-6',n:6,level:'مبتدئ',domain:'أوامر التداول',updated:'2026-10-14',
title:'إزاي تقرا رسالة توصية: Entry, Target, Stop Loss, Support, Resistance',
short:'المصطلحات الإنجليزي اللي بتتكرر في قنوات التداول، بمثال رسالة كاملة.',
summary:'<p>رسالة زي «🔥 شراء XYZ دخول 25 هدف 28 وقف 23.5» فيها 3 أرقام: <b>[[entry|الدخول]]</b> (هتشتري بكام)، <b>[[takeprofit|الهدف]]</b> (تتمنى تبيع بكام)، <b>[[stoploss|الوقف]]</b> (هتبيع بخسارة لو نزل لكام). الهدف <b>توقع</b>، والوقف <b>حماية</b>.</p>',
body:'<ol class="steps"><li><b>[[marketorder|أمر السوق]]</b>: اشتري حالًا بأي سعر متاح.</li><li><b>[[limitorder|الأمر المحدد]]</b>: اشتري بس لو السعر وصل للرقم ده.</li><li><b>[[stoploss|وقف الخسارة]]</b>: بيع تلقائي لو السعر نزل لحد معين.</li><li><b>[[support|الدعم]]</b> و<b>[[resistance|المقاومة]]</b>: مستويات «اتعوّد» السعر يرتد عندها في الماضي — مش قوانين.</li><li><b>[[rr|نسبة العائد للمخاطرة]]</b>: (الهدف − الدخول) ÷ (الدخول − الوقف).</li></ol>',
examples:[{title:'مثال: تحليل رسالة توصية افتراضية',kind:'hypothetical',open:true,html:'<div class="quote">شراء سهم XYZ — دخول 25 — هدف 28 — وقف خسارة 23.5</div>'+CALC([['المكسب المحتمل للسهم','28 − 25','3 جنيه (12%)'],['الخسارة المحتملة للسهم','25 − 23.5','1.5 جنيه (6%)'],['=نسبة العائد للمخاطرة','3 ÷ 1.5','1:2'],['لو اشتريت 400 سهم','400 × 25','10,000 جنيه'],['أقصى خسارة متوقعة (قبل الرسوم والفجوات)','400 × 1.5','600 جنيه'],['المكسب لو الهدف اتحقق (قبل الرسوم)','400 × 3','1,200 جنيه']])+
'<p><b>الأسئلة اللي الرسالة ماجاوبتش عليها:</b> ليه 28؟ إيه الدليل؟ إمتى اتبعتت (لو اتأخرت ساعة السعر ممكن يكون طلع 27)؟ الشركة دي نشاطها إيه وحكمها الشرعي؟ صاحب القناة نفسه شاري السهم ده؟ وكام توصية قبل كده ضربت الوقف؟</p>'}],
shariah:'<p>استخدام أوامر البيع والشرا ووقف الخسارة على أسهم مملوكة بفلوسك مجرد <b>وسيلة تنفيذ</b>، وحكمها تابع لحكم الأصل نفسه. لكن «الدخول والهدف والوقف» على [[cfd|عقد فروقات]] أو برافعة بقرض بيدخلها في إشكالات تانية.</p>',
risks:'<ul><li>الوقف ممكن يتنفذ بسعر أسوأ لو السعر «فجّ» (فتح تحت الوقف).</li><li>إنك تشيل الوقف لما السعر يقرّب منه «عشان ميضربش».</li><li>الدخول المتأخر بعد ما المشتركين كلهم اشتروا.</li></ul>',
checklist:['الرسالة فيها سبب واضح للتوصية؟','عارف وقت إرسالها والسعر وقتها؟','حسبت أقصى خسارة بالجنيه مش بالنسبة بس؟','الأصل نفسه اتفحص شرعيًا؟','فيه سجل كامل للتوصيات القديمة (الكسبانة والخسرانة)؟'],
todo:['خد أي رسالة توصية وحلّلها بنفس الجدول (من غير ما تنفذها).','افتح <a href="#/recs">سجل التوصيات</a> وشوف إزاي بنسجلها.'],
known:['معنى كل رقم في الرسالة وطريقة الحساب.'],unknown:['هل الهدف هيتحقق — محدش يعرف.'],
quiz:[
{q:'دخول 50، هدف 56، وقف 47. نسبة العائد للمخاطرة:',opts:['1:1','1:2','1:3'],a:1,why:'العائد 6، المخاطرة 3 → 6 ÷ 3 = 2، يعني 1:2.'},
{q:'«الدعم عند 20» معناه:',opts:['السعر مستحيل ينزل تحت 20','السعر ارتد من عند 20 في الماضي وممكن يكسره','البورصة بتدعم السهم'],a:1,why:'الدعم وصف لتاريخ السعر، مش ضمان.'},
{q:'وقف الخسارة بيضمن إن خسارتك مش هتزيد عن الرقم بالظبط؟',opts:['أيوه دايمًا','لأ، ممكن يتنفذ بسعر أسوأ لو حصلت فجوة سعرية','الوقف بيمنع الخسارة خالص'],a:1,why:'لو السهم فتح تحت الوقف، هيتنفذ بأول سعر متاح.'}]},

/* ======================================================= 7 */
{id:'money-7',n:7,level:'متوسط',domain:'إدارة المخاطر',updated:'2026-10-14',
title:'إدارة رأس المال: حجم الصفقة، نسبة النجاح، والخسائر المتتالية',
short:'ليه «نسبة نجاح 90%» ممكن تخسّرك، وليه الخسارة الكبيرة صعب تتعوض.',
summary:'<ul><li>حدد <b>أقصى خسارة</b> بالجنيه قبل ما تحدد هتشتري كام.</li><li><b>نسبة النجاح لوحدها مضللة</b>: المهم متوسط المكسب مقابل متوسط الخسارة.</li><li>خسارة 50% محتاجة مكسب <b>100%</b> عشان ترجع.</li></ul>',
body:'<ol class="steps"><li><b>[[positionsize|حجم الصفقة]]</b> = أقصى خسارة تقبلها ÷ (الدخول − الوقف).</li><li><b>[[expectancy|التوقع الرياضي]]</b> = (نسبة الكسب × متوسط المكسب) − (نسبة الخسارة × متوسط الخسارة) − الرسوم.</li><li><b>[[drawdown|التراجع]]</b>: كل ما الخسارة تكبر، المكسب المطلوب للتعويض يكبر أسرع.</li><li><b>مفيش استراتيجية بتكسب دايمًا</b>: السوق بيتغير، وأي طريقة نجحت في فترة ممكن تفشل في فترة تانية. اللي بيقول غير كده بيبيع وهم.</li></ol>',
examples:[
{title:'مثال 1: حساب حجم الصفقة',kind:'hypothetical',open:true,html:'<p><b>الافتراضات:</b> رأس مال 50,000 — أقصى مخاطرة في الصفقة 1% — دخول 20 — وقف 18.</p>'+CALC([['أقصى خسارة مقبولة','50,000 × 1%','500 جنيه'],['الخسارة للسهم الواحد','20 − 18','2 جنيه'],['=عدد الأسهم','500 ÷ 2','250 سهم'],['قيمة الصفقة','250 × 20','5,000 جنيه (10% من رأس المال)']])},
{title:'مثال 2: نسبة نجاح 70% ومع ذلك خسران',kind:'hypothetical',open:true,html:CALC([['7 صفقات كسبانة × 100','7 × 100','+700'],['3 صفقات خسرانة × 300','3 × 300','−900'],['=النتيجة (قبل الرسوم)','700 − 900','−200']])+'<p>وفي المقابل: نسبة نجاح 40% بس مع مكسب 300 وخسارة 100: (4 × 300) − (6 × 100) = +600.</p>'},
{title:'مثال 3: الخسائر المتتالية',kind:'hypothetical',html:'<p><b>الافتراض:</b> 100,000 جنيه و5 خسائر ورا بعض.</p><div class="table-wrap"><table class="calc"><thead><tr><th>المخاطرة في كل صفقة</th><th>بعد 5 خسائر</th><th>النقص</th></tr></thead><tbody><tr><td>2%</td><td>100,000 × 0.98⁵ ≈ 90,392</td><td>−9.6%</td></tr><tr><td>10%</td><td>100,000 × 0.90⁵ ≈ 59,049</td><td>−41%</td></tr><tr><td>25%</td><td>100,000 × 0.75⁵ ≈ 23,730</td><td>−76%</td></tr></tbody></table></div>'},
{title:'مثال 4: كام محتاج تكسب عشان ترجع؟',kind:'hypothetical',html:'<div class="bar-row"><span>خسارة 10%</span><span class="bar"><i style="width:2%"></i></span><span>+11.1%</span></div><div class="bar-row"><span>خسارة 20%</span><span class="bar"><i style="width:5%"></i></span><span>+25%</span></div><div class="bar-row"><span>خسارة 30%</span><span class="bar"><i style="width:9%"></i></span><span>+42.9%</span></div><div class="bar-row"><span>خسارة 50%</span><span class="bar"><i style="width:22%"></i></span><span>+100%</span></div><div class="bar-row"><span>خسارة 70%</span><span class="bar"><i class="neg" style="width:52%"></i></span><span>+233%</span></div><div class="bar-row"><span>خسارة 90%</span><span class="bar"><i class="neg" style="width:100%"></i></span><span>+900%</span></div><p>المعادلة: المكسب المطلوب = 1 ÷ (1 − نسبة الخسارة) − 1.</p>'}],
shariah:'<p>حفظ المال من مقاصد الشريعة. والدخول في مخاطرة تقدر توصل لضياع رأس المال كله من غير دراسة قريب من التهلكة والتغرير بالنفس. <b>إدارة المخاطر مش رفاهية</b>.</p><p><b>المخاطرة المحسوبة vs المقامرة:</b> المخاطرة المحسوبة = أصل حقيقي مفهوم، خسارة قصوى محددة تقدر تتحملها، وقرار مبني على معلومات. المقامرة = رهان على نتيجة مش مفهومة، والخسارة ممكن تبقى كل حاجة، والمكسب جاي من خسارة غيرك.</p>',
risks:'<ul><li>«هعوض الخسارة في الصفقة الجاية» → تكبير الحجم بعد الخسارة.</li><li>الانبهار بنسبة نجاح من غير ما تسأل عن حجم الخسائر.</li><li>تصديق إن فيه استراتيجية مضمونة.</li></ul>',
checklist:['حددت أقصى خسارة بالجنيه قبل الدخول؟','الخسارة دي لو حصلت 5 مرات ورا بعض أقدر أتحملها؟','بسأل عن متوسط المكسب والخسارة مش نسبة النجاح بس؟'],
todo:['احسب حجم صفقة افتراضية برأس مال افتراضي بالمعادلة.','لو قناة بتقول «نسبة نجاح 90%»، اطلب السجل الكامل بالأرقام.'],
known:['المعادلات أعلاه رياضيات ثابتة.'],unknown:['نسبة النجاح المستقبلية لأي طريقة.'],
quiz:[
{q:'خسرت 50% من محفظتك. محتاج تكسب كام عشان ترجع؟',opts:['50%','100%','75%'],a:1,why:'لو معاك 100 بقوا 50، محتاج 50 زيادة على الـ 50 = 100%.'},
{q:'رأس مال 20,000 ومخاطرة 1%، دخول 10 ووقف 9.5. كام سهم؟',opts:['200','400','2,000'],a:1,why:'200 ÷ 0.5 = 400 سهم.'},
{q:'قناة بتقول نسبة نجاحها 90%. ده يكفي عشان أعرف إنها مربحة؟',opts:['أيوه','لأ، لازم أعرف متوسط الكسب والخسارة والسجل الكامل','أيوه لو المشتركين كتير'],a:1,why:'خسارة واحدة كبيرة ممكن تمسح 9 مكاسب صغيرة.'}]},

/* ======================================================= 8 */
{id:'leverage-8',n:8,level:'متوسط',domain:'الرافعة والهامش',updated:'2026-10-14',
title:'الرافعة المالية والهامش والتصفية: الحساب والحكم',
short:'إزاي فلوس متسلفة بتكبّر الخسارة، وليه أغلب المجامع منعت الصور المنتشرة منها.',
summary:'<p>[[leverage|الرافعة]] = تتداول بفلوس أكتر من فلوسك، والفرق قرض. بتكبّر المكسب والخسارة بنفس القوة. في رافعة 1:100، حركة 1% عكسك = خسارة كل فلوسك.</p><p>شرعًا: الصورة المنتشرة فيها <b>قرض بفايدة</b> أو <b>قرض مشروط بالتداول عند نفس السمسار</b> — والمجامع الفقهية منعتها.</p>',
body:'<ol class="steps"><li>إنت بتحط [[margin|هامش]] (ضمان) والسمسار بيكمل الباقي.</li><li>لو السعر اتحرك عكسك، الخسارة بتتخصم من هامشك إنت.</li><li>لما الهامش يقرّب يخلص: [[margincall|طلب تغطية]] ← لو ماحطيتش فلوس: [[liquidation|تصفية إجبارية]].</li><li>لو سبت الصفقة مفتوحة لليوم اللي بعده: [[swap|رسوم تبييت]] = فايدة على المبلغ المموّل.</li></ol>'+
'<figure class="diagram"><svg viewBox="0 0 640 170" role="img" aria-label="تدفق الأموال في التداول بالهامش"><g font-family="inherit" font-size="13" fill="currentColor"><rect x="440" y="20" width="180" height="56" rx="10" fill="none" stroke="currentColor" opacity=".5"/><text x="530" y="44" text-anchor="middle">إنت: هامش 10,000</text><text x="530" y="64" text-anchor="middle" opacity=".7">فلوسك</text><rect x="440" y="100" width="180" height="56" rx="10" fill="none" stroke="currentColor" opacity=".5"/><text x="530" y="124" text-anchor="middle">السمسار: قرض 90,000</text><text x="530" y="144" text-anchor="middle" opacity=".7">+ فايدة/رسوم أو شرط تداول</text><path d="M440 48 L330 82 M440 128 L330 92" stroke="currentColor" opacity=".5" fill="none"/><rect x="170" y="60" width="160" height="56" rx="10" fill="none" stroke="currentColor"/><text x="250" y="84" text-anchor="middle">صفقة 100,000</text><text x="250" y="104" text-anchor="middle" opacity=".7">رافعة 1:10</text><path d="M170 88 L120 88" stroke="currentColor" opacity=".5"/><text x="60" y="80" text-anchor="middle">لو السعر نزل 10%</text><text x="60" y="100" text-anchor="middle">خسارة 10,000</text><text x="60" y="120" text-anchor="middle" opacity=".7">هامشك كله راح</text></g></svg><figcaption>الخسارة كلها بتتخصم من فلوسك إنت، والقرض لازم يرجع للسمسار كامل.</figcaption></figure>',
examples:[{title:'مثال: 10,000 جنيه من غير رافعة vs برافعة 1:10',kind:'hypothetical',open:true,html:'<div class="table-wrap"><table class="calc"><thead><tr><th>حركة السعر</th><th>بفلوسك بس (صفقة 10,000)</th><th>برافعة 1:10 (صفقة 100,000)</th></tr></thead><tbody><tr><td>+5%</td><td>+500 (+5%)</td><td>+5,000 (+50% من فلوسك)</td></tr><tr><td>−5%</td><td>−500 (−5%)</td><td>−5,000 (−50% من فلوسك)</td></tr><tr><td>−10%</td><td>−1,000 (−10%)</td><td>−10,000 (−100%) ← تصفية</td></tr></tbody></table></div><p>وده <b>قبل</b> رسوم التبييت والعمولات. مثال التبييت: 90,000 مموّلين بفايدة سنوية 20% (افتراض) → 90,000 × 20% ÷ 365 ≈ 49 جنيه كل يوم.</p>'},
{title:'مثال من الفوركس: رافعة 1:100',kind:'hypothetical',html:CALC([['فلوسك','1,000$'],['حجم الصفقة برافعة 1:100','1,000 × 100','100,000$'],['حركة 1% عكسك','100,000 × 1%','−1,000$'],['=المتبقي من فلوسك','1,000 − 1,000','0 (وغالبًا بتتصفى قبلها)']])}],
cases:['C04','C03'],
shariah:'<h3>الحكم المنقول</h3><ul><li><b>المجمع الفقهي الإسلامي برابطة العالم الإسلامي</b> قرر في المتاجرة بالهامش: عدم جوازها، لاشتمالها على الربا (القرض بفايدة أو رسوم التبييت) ولأن اشتراط الوسيط أن يكون التداول عن طريقه يجمع بين سلف ومعاوضة {{F18,F44}}.</li><li><b>مجمع الفقه الإسلامي الدولي</b> منع شراء الأسهم بقرض ربوي (الشراء بالهامش) ضمن قراره عن الأسواق المالية {{F02}}.</li><li>الحديث: «لا يحل سلف وبيع» {{F73}}.</li></ul><h3>التحليل التعاقدي</h3><p>الرافعة مش «اسم» واحد: فيه 3 أسئلة بتحدد الحكم: (1) فيه قرض فعلًا؟ (2) القرض بفايدة أو رسوم مربوطة بالمبلغ والمدة؟ (3) القرض مشروط بإنك تتداول عند نفس الجهة وتدفع لها عمولة؟ لو أي واحد من (2) أو (3) موجود → الإشكال قائم حتى لو المنصة سمّته «إسلامي».</p>',
dispute:'<p><b>فيه خلاف حقيقي لازم تعرفه:</b></p><ul><li><b>المنع:</b> المجمع الفقهي برابطة العالم الإسلامي {{F18,F44}}، ومجمع الفقه الإسلامي الدولي (شراء السهم بقرض ربوي من السمسار) {{F02}}، والمعيار الشرعي 21 لأيوفي {{F26}}.</li><li><b>الجواز:</b> دار الإفتاء المصرية أفتت إن «توفير تمويل شراء الأوراق المالية بالهامش» في البورصة المصرية بقواعد الهيئة العامة للرقابة المالية «عقد تمويل» جائز {{F63}}. الفتوى مبنية على إن الدار بتكيّف تمويل البنوك عمومًا إنه «عقد تمويل» مش قرض ربوي — وده تكييف بتخالفه المجامع.</li></ul><p>يعني: الهامش في البورصة المصرية <b>محل خلاف معتبر</b>، وقول المجامع الجماعية هو المنع. وفيه كمان نقاش في صور بديلة (زي تمويل بمرابحة حقيقية لشراء أسهم مباحة، أو تمويل بدون أي عائد ولا شرط تداول) — والحكم فيها بيتوقف على العقد الفعلي، ومحتاج مراجعة متخصص.</p>',
risks:'<ul><li>الخسارة ممكن تتعدى فلوسك في بعض المنتجات.</li><li>التصفية بتحصل في أسوأ لحظة.</li><li>«الحساب الإسلامي» بيلغي اسم الفايدة بس ساعات بيحط رسوم بديلة.</li></ul>',
checklist:['فيه قرض؟ من مين؟','القرض عليه فايدة أو رسوم بالمدة؟','القرض مشروط بالتداول عند نفس السمسار؟','حسبت حركة السعر اللي تمسح الهامش كله؟'],
todo:['اقرا تحليل رسالة «الفوركس الإسلامي» في <a href="#/messages">تحليل الرسائل</a>.','لو منصة عرضت عليك رافعة، اطلب العقد واقرا بند «التمويل» و«الرسوم».'],
known:['حساب الرافعة ثابت رياضيًا.','قرارات المجامع المذكورة بمنع الصورة المنتشرة.','دار الإفتاء المصرية أجازت الهامش المنظم في البورصة المصرية — فالمسألة خلافية.'],unknown:['حكم صيغة تمويل بعينها عند جهة بعينها من غير قراءة عقدها.'],
quiz:[
{q:'فلوسك 5,000 ورافعة 1:20. السعر نزل 5%. خسرت كام؟',opts:['250','5,000 (كل فلوسك)','2,500'],a:1,why:'الصفقة 100,000 × 5% = 5,000 = كل الهامش.'},
{q:'«رسوم التبييت» حقيقتها غالبًا:',opts:['عمولة تنفيذ','فايدة على المبلغ الممول','ضريبة حكومية'],a:1,why:'بتتحسب بالمدة وبحجم التمويل، ودي طبيعة الفايدة.'},
{q:'لو المنصة ألغت التبييت وسمت الحساب «إسلامي»، يبقى خلاص متوافق؟',opts:['أيوه','مش بالضرورة: لازم أشوف القرض واشتراط التداول والرسوم البديلة','أيوه لو فيه هيئة شرعية'],a:1,why:'العبرة بحقيقة العقد مش باسمه.'}]},

/* ======================================================= 9 */
{id:'deriv-9',n:9,level:'متقدم',domain:'المشتقات',updated:'2026-10-14',
title:'المشتقات: العقود الآجلة، المستقبليات، الخيارات، CFDs، والخيارات الثنائية',
short:'عقود على «السعر» مش على «الحاجة» — بالأمثلة، وقرارات المجامع فيها.',
summary:'<p>[[derivative|المشتقات]] عقود قيمتها جاية من سعر حاجة تانية. أغلب استخدام الأفراد ليها = رهان على السعر برافعة، من غير ما يملكوا الأصل. المجامع الفقهية منعت أشهر صورها، والنقاش مستمر في بعض صور التحوط.</p>',
body:'<ol class="steps"><li><b>[[forward|العقد الآجل]]</b>: اتفاق النهارده على تسليم ودفع بعدين.</li><li><b>[[futures|المستقبليات]]</b>: آجل موحّد في بورصة، وأغلبه بيتقفل بفرق السعر.</li><li><b>[[options|الخيارات]]</b>: تدفع علاوة عشان «حق» الشرا أو البيع بسعر محدد.</li><li><b>[[cfd|عقود الفروقات]]</b>: إنت والمنصة بتتحاسبوا على فرق السعر بس.</li><li><b>[[binary|الخيارات الثنائية]]</b>: «هيطلع ولا هينزل في دقيقة؟» — كله أو ولا حاجة.</li></ol>',
examples:[{title:'مثال: نفس التوقع بثلاث طرق',kind:'hypothetical',open:true,html:'<p>إنت متوقع سهم سعره 100 يطلع. معاك 1,000 جنيه.</p><div class="table-wrap"><table class="calc"><thead><tr><th>الطريقة</th><th>لو بقى 110</th><th>لو بقى 90</th></tr></thead><tbody><tr><td>تشتري 10 أسهم حقيقية</td><td>+100</td><td>−100 (ولسه معاك الأسهم)</td></tr><tr><td>CFD برافعة 1:10 (عقد على 100 سهم)</td><td>+1,000</td><td>−1,000 (فلوسك كلها)</td></tr><tr><td>خيار شراء: علاوة 5 للسهم × 200 سهم = 1,000، سعر التنفيذ 100</td><td>200 × (10 − 5) = +1,000</td><td>−1,000 (العلاوة راحت)</td></tr></tbody></table></div><p>ومثال الخيارات الثنائية: حطيت 100$ على «هيطلع خلال دقيقة». صح → تاخد مثلًا 180$. غلط → 0. لو نسبة نجاحك 50% بالظبط: (0.5 × 80) − (0.5 × 100) = −10$ في المتوسط كل مرة.</p>'}],
cases:['C07'],
shariah:'<h3>الحكم المنقول</h3><ul><li>مجمع الفقه الإسلامي الدولي في قراره عن الأسواق المالية: عقود الاختيارات غير جائزة إنشاءً ولا تداولًا، والعقود المستقبلية بصورتها في الأسواق غير جائزة، وكذلك التعامل في المؤشرات {{F02}}.</li><li>في العملات: لا يجوز البيع الآجل للعملات ولا المواعدة الملزمة على الصرف {{F01}}.</li><li>فتاوى في عقود الفروقات {{F30,F47}} والخيارات الثنائية {{F32,F49}}.</li></ul><h3>العلة باختصار</h3><ul><li><b>لا تملك ولا قبض</b> للأصل (بيع ما ليس عندك) {{F74}}.</li><li><b>غرر</b> كبير، وفي الثنائية شبه واضح بـ<b>الميسر</b> {{F69}}.</li><li>غالبًا معاها <b>رافعة بقرض</b>.</li></ul>',
dispute:'<p>فيه نقاش معاصر في أدوات <b>التحوط</b> البديلة (زي الوعد من طرف واحد، أو عقد السَّلَم في السلع بشروطه). أيوفي أصدرت معيار للسلع في الأسواق المنظمة يفصّل الصور الجائزة والممنوعة {{F25}}. الحكم على أداة تحوط بعينها في بنك محتاج قراءة العقد.</p>',
risks:'<ul><li>الخسارة ممكن تتعدى المبلغ المدفوع (في المستقبليات والبيع على المكشوف).</li><li>منصات CFD والثنائية الأجنبية غالبًا مش مرخصة في مصر.</li></ul>',
checklist:['هل بملك الأصل فعلًا ولا بتعامل على سعره بس؟','فيه رافعة؟','المنصة مرخصة من جهة رقابية في بلدي؟','الخسارة القصوى محدودة ولا مفتوحة؟'],
todo:['روح <a href="#/compare">المقارنات</a>: «سهم حقيقي vs CFD».','لو حد عرض عليك «تداول ذهب أونلاين»، اسأل: هستلم ذهب ولا عقد؟'],
known:['آلية كل نوع.','قرارات المجامع في الخيارات والمستقبليات والصرف الآجل.'],unknown:['حكم منتج تحوط معين في بنك معين بدون عقده.'],
quiz:[
{q:'في عقد CFD على الذهب، إنت بتستلم ذهب؟',opts:['أيوه','لأ، بتتحاسب على فرق السعر بس','نص الكمية'],a:1,why:'CFD عقد على الفرق؛ مفيش تسليم.'},
{q:'الخيارات الثنائية أقرب لإيه؟',opts:['استثمار طويل','رهان «كل حاجة أو ولا حاجة»','ادخار'],a:1,why:'نتيجتها ثنائية: تكسب نسبة أو تخسر المبلغ كله.'},
{q:'قرار مجمع الفقه الدولي في عقود الاختيارات:',opts:['جائزة','غير جائزة إنشاءً ولا تداولًا','جائزة للتحوط بس'],a:1,why:'ده نص القرار في الأسواق المالية.'}]},

/* ======================================================= 10 */
{id:'forex-10',n:10,level:'متوسط',domain:'الفوركس والعملات',updated:'2026-10-14',
title:'الفوركس و«الحساب الإسلامي»: إيه اللي بيحصل فعلًا؟',
short:'الفرق بين صرافة حقيقية جائزة، وتداول عملات أونلاين بالرافعة.',
summary:'<p>تبديل العملات <b>يدًا بيد</b> (فوري، وكل طرف بيستلم) جائز بالإجماع تقريبًا. «الفوركس» المنتشر أونلاين للأفراد مختلف: فيه [[leverage|رافعة]] بقرض، وغالبًا [[cfd|CFD]] من غير تسليم، و[[swap|تبييت]]. «الحساب الإسلامي» بيشيل التبييت بس.</p>',
body:'<ol class="steps"><li><b>الصرف الشرعي:</b> «الذهب بالذهب، والفضة بالفضة… يدًا بيد» {{F71,F70}}. العملات الورقية أخذت حكم الذهب والفضة في وجوب التقابض عند المجامع.</li><li><b>اللي بيحصل في منصة فوركس:</b> بتحط 1,000$، المنصة بتديك قوة شرائية 100,000$ (قرض)، وبتتحاسب على فرق السعر.</li><li><b>«أركان الفوركس» عند صاحب القناة</b> (صورة اقتباس منشورة): الرافعة = قرض جر نفع، اشتراط التداول عند السمسار = سلف وبيع، رسوم التبييت = فايدة. وده متسق مع قرار مجمع الرابطة {{F18,F44}}.</li><li><b>«الحساب الإسلامي»:</b> بيلغي التبييت، لكن بيفضل فيه القرض واشتراط التداول — وأحيانًا رسوم بديلة.</li></ol>',
examples:[{title:'مثال: صرافة حقيقية vs فوركس بالرافعة',kind:'hypothetical',open:true,html:'<div class="table-wrap"><table><thead><tr><th>البند</th><th>صرافة في بنك/صرافة</th><th>منصة فوركس</th></tr></thead><tbody><tr><td>إيه اللي بيحصل</td><td>تدي 5,000 جنيه وتستلم دولارات في حسابك فورًا</td><td>تحط 1,000$ وتفتح صفقة 100,000$ يورو/دولار</td></tr><tr><td>تملك العملة؟</td><td>أيوه</td><td>غالبًا لأ (عقد على السعر)</td></tr><tr><td>قرض؟</td><td>لأ</td><td>أيوه 99,000$</td></tr><tr><td>حركة 1% عكسك</td><td>خسارة 1% من فلوسك</td><td>خسارة 100% من فلوسك</td></tr></tbody></table></div>'},
{title:'مثال: «الفوركس الإسلامي» من رسالة القناة (5 نوفمبر 2024)',kind:'hypothetical',html:'<p>الرسالة بتوصف: حساب 200 ألف + رافعة لحد مليون، يعني 800 ألف «سلفة»، وتقسيم ربح 80% للمتداول و20% للسمسار.</p>'+CALC([['قوة التداول','1,000,000'],['فلوس المتداول','200,000'],['=المبلغ الممول (سلفة)','1,000,000 − 200,000','800,000'],['حركة 5% لصالحه','1,000,000 × 5%','+50,000'],['نصيب المتداول 80%','50,000 × 80%','40,000'],['حركة 20% عكسه','1,000,000 × 20%','−200,000 = كل فلوسه']])+'<p>شوف تحليل الرسالة كاملة في <a href="#/messages">تحليل الرسائل</a>.</p>'}],
shariah:'<h3>الحكم المنقول</h3><ul><li>قرار مجمع الفقه الدولي في تجارة العملات: لا يجوز البيع الآجل للعملات، ولا المواعدة على الصرف {{F01}}.</li><li>قرار مجمع الرابطة في المتاجرة بالهامش {{F18,F44}}.</li><li>معيار أيوفي رقم 1 «المتاجرة في العملات» {{F20}}.</li><li>فتوى في الفوركس عبر الإنترنت {{F17,F28,F62}}.</li></ul>',
dispute:'<p>الاتفاق قائم على جواز الصرف الفوري بالتقابض، وعلى منع الصرف المؤجل. الخلاف بيقل جدًا في الصورة المنتشرة بالرافعة الربوية. النقاش الحقيقي في: هل القيد الإلكتروني في الحساب يكفي كقبض حكمي في المنصات؟ وهل التسوية بعد يومين (T+2) في سوق الصرف الدولي تؤثر؟ — مسائل محتاجة متخصص.</p>',
risks:'<ul><li>منصات غير مرخصة، وصعوبة سحب الفلوس.</li><li>أغلب الأفراد بيخسروا في التداول بالرافعة.</li></ul>',
checklist:['هستلم العملة فعلًا في حسابي؟','فيه قرض؟ بشروط إيه؟','المنصة مرخصة من جهة رقابية معروفة؟','الحساب «الإسلامي» فيه رسوم بديلة عن التبييت؟'],
todo:['اقرا مقارنة «منتج اسمه حساب إسلامي vs فحص شروطه الفعلية».','لو محتاج دولار لسفر أو استيراد: الصرافة الحقيقية من جهة مرخصة هي الصورة الواضحة.'],
known:['جواز الصرف يدًا بيد ومنع المؤجل في قرارات المجامع.'],unknown:['شروط منصة بعينها — لازم تقرا العقد.'],
quiz:[
{q:'إيه شرط الصرف (تبديل عملة بعملة)؟',opts:['التقابض في المجلس (يدًا بيد)','وجود سمسار','رافعة'],a:0,why:'حديث «يدًا بيد» وقرارات المجامع.'},
{q:'«الحساب الإسلامي» في الفوركس عادةً بيلغي:',opts:['الرافعة','رسوم التبييت','القرض'],a:1,why:'غالبًا التبييت بس؛ القرض والرافعة بيفضلوا.'},
{q:'رافعة 1:100 معناها حركة كام % تمسح فلوسك؟',opts:['10%','1%','50%'],a:1,why:'100,000 × 1% = 1,000 = كل الهامش.'}]},

/* ======================================================= 11 */
{id:'stocks-11',n:11,level:'متوسط',domain:'الأسهم الشرعية',updated:'2026-10-14',
title:'إزاي تعرف السهم متوافق مع الشريعة؟ النشاط، النسب، والتطهير',
short:'الشركات «المختلطة» والمعيار الشرعي 21 وحساب التطهير بالأرقام — والخلاف فيها.',
summary:'<p>خطوتين: <b>(1) النشاط</b>: الشركة بتعمل إيه؟ لو نشاطها الأساسي محرم (بنوك ربوية، خمور، قمار…) → مستبعدة. <b>(2) النسب المالية</b>: ديون بفايدة، ودائع بفايدة، إيرادات محرمة — لازم تكون تحت حدود معينة عند اللي بيجيزوا الشركات المختلطة، ومع <b>تطهير</b> الجزء المحرم من الربح.</p>',
body:'<ol class="steps"><li><b>فحص النشاط:</b> اقرا وصف نشاط الشركة وإيراداتها حسب القطاعات.</li><li><b>فحص الديون:</b> القروض بفايدة ÷ القيمة السوقية (أو إجمالي الأصول حسب المعيار).</li><li><b>فحص الودائع والاستثمارات بفايدة:</b> ودائع ربوية ÷ القيمة السوقية.</li><li><b>فحص الإيراد المحرم:</b> فوايد وإيرادات من نشاط محرم ÷ إجمالي الإيرادات.</li><li><b>[[purification|التطهير]]:</b> تطلّع نسبة الإيراد المحرم من أرباحك.</li><li><b>[[preferred|الأسهم الممتازة]]</b> بامتياز مالي: ممنوعة الإصدار عند المجمع.</li></ol>'+
'<div class="callout info"><div><b class="t">نسب المعيار الشرعي 21 (أيوفي)</b><p>النسب كما في المعيار: إجمالي القروض الربوية لا يزيد عن 30% من القيمة السوقية، والودائع/الاستثمارات الربوية لا تزيد عن 30% من القيمة السوقية، والإيراد من عنصر محرم لا يزيد عن 5% من إجمالي الإيرادات {{F26}}. جهات تانية بتستخدم نسب أو طرق حساب مختلفة (مثلًا 33% أو على إجمالي الأصول).</p></div></div>',
examples:[{title:'مثال: فحص شركة افتراضية «ألف للأسمنت»',kind:'hypothetical',open:true,html:'<p><b>البيانات (افتراضية):</b> القيمة السوقية 2,000 مليون — قروض بفايدة 500 مليون — ودائع بفايدة 300 مليون — إجمالي الإيرادات 1,200 مليون منها 36 مليون فوايد بنكية.</p>'+CALC([['نسبة القروض الربوية','500 ÷ 2,000','25% (أقل من 30% ✓)'],['نسبة الودائع الربوية','300 ÷ 2,000','15% (أقل من 30% ✓)'],['نسبة الإيراد المحرم','36 ÷ 1,200','3% (أقل من 5% ✓)'],['=النتيجة حسب نسب المعيار 21','تعدّي النسب — مع وجوب التطهير']])+'<p><b>التطهير:</b> لو وزعت عليك الشركة 2,000 جنيه أرباح → 2,000 × 3% = <b>60 جنيه</b> تطلعهم في وجوه الخير.</p><p><b>تنبيه:</b> عند المجمع الفقهي برابطة العالم الإسلامي، الشركة دي <b>غير جائزة</b> أصلًا لأنها بتتعامل بالربا (شوف الخلاف تحت). وبيانات الشركة بتتغير كل ربع سنة، فالنتيجة بتتغير.</p>'}],
shariah:'<h3>الحكم المنقول</h3><ul><li>المعيار الشرعي 21 (الأوراق المالية) — أيوفي: جواز الاستثمار في الشركات المختلطة بالضوابط والنسب مع التطهير {{F26}}.</li><li>المجمع الفقهي برابطة العالم الإسلامي: عدم جواز شراء أسهم الشركات التي تتعامل بالربا وإن كان أصل نشاطها مباحًا {{F19,F34}}.</li><li>مجمع الفقه الدولي — الأسهم الممتازة: لا يجوز إصدار أسهم ممتازة لها خصائص مالية تؤدي إلى ضمان رأس المال أو قدر من الربح {{F02}}.</li></ul>',
dispute:'<p><b>الخلاف هنا معتبر وحقيقي:</b></p><ul><li><b>مجمع الفقه الإسلامي الدولي:</b> قرر في الأسواق المالية إن «الأصل حرمة» الإسهام في شركات بتتعامل أحيانًا بالمحرمات زي الربا {{F02}}، وبعدين في دورته التاسعة <b>أجّل</b> البت في الشركات اللي نشاطها مباح وبتقترض أو تودع بفايدة لمزيد من الدراسة {{F11}} — ومالقيناش قرار لاحق يحسمها.</li><li><b>المانعون</b> (مجمع الرابطة، وجمع من العلماء): المساهم شريك وموكِّل للإدارة، فهو مشارك في تعاملها بالربا ولو قليلًا {{F19,F34}}.</li><li><b>المجيزون بضوابط</b> (أيوفي وهيئات شرعية لبنوك إسلامية): لعموم البلوى والحاجة، ولأن المحرم يسير وتابع، مع اشتراط النسب والتطهير وإنكار المخالفة {{F26}} {{F35,F53,F55}}.</li></ul><p>صاحب القناة نفسه قال إن الشركات المختلطة هي «المشكلة الكبرى» وأحال على المعيار 21 — يعني هو بيتبع طريقة النسب والتطهير.</p>',
risks:'<ul><li>نتيجة الفحص بتتغير كل ما القوائم المالية تتغير.</li><li>جهتين ممكن يختلفوا على نفس الشركة بسبب اختلاف طريقة الحساب.</li><li>«السهم متوافق» ≠ «السهم هيكسب».</li></ul>',
checklist:['النشاط الأساسي مباح؟','عندي آخر قوائم مالية؟','حسبت النسب التلاتة؟','عارف المعيار اللي بطبقه (أيوفي؟ غيره؟)','عارف إن فيه رأي بيمنع الشركات المختلطة أصلًا؟','هطهّر الأرباح؟'],
todo:['اختار شركة وحمّل قوائمها المالية من موقع البورصة وجرّب تحسب النسب بنفسك (تمرين، مش قرار).','اقرا تحليل بوست «الاستثمار في البورصة» في <a href="#/messages">تحليل الرسائل</a>.'],
known:['نسب المعيار 21 كما وردت فيه.','وجود خلاف معتبر بين المجامع.'],unknown:['تصنيف أي شركة مصرية بعينها اليوم — محتاج قوائمها الحالية.'],
quiz:[
{q:'شركة إيراداتها 1,000 مليون منها 70 مليون فوايد. حسب نسبة 5% للإيراد المحرم:',opts:['تعدّي','ماتعدّيش (7%)','مش مهم'],a:1,why:'70 ÷ 1,000 = 7% > 5%.'},
{q:'كسبت 5,000 أرباح ونسبة الإيراد المحرم 2%. التطهير:',opts:['100 جنيه','50 جنيه','مفيش'],a:0,why:'5,000 × 2% = 100.'},
{q:'هل كل العلماء بيجيزوا الشركات المختلطة بالنسب؟',opts:['أيوه، إجماع','لأ، فيه خلاف معتبر (مجمع الرابطة منع)','كلهم منعوا'],a:1,why:'المسألة خلافية بين المجامع والهيئات.'}]},

/* ======================================================= 12 */
{id:'islamic-12',n:12,level:'متوسط',domain:'التمويل الإسلامي',updated:'2026-10-14',
title:'الصناديق والصكوك والمرابحة والمشاركة: إمتى يبقى «إسلامي» بجد؟',
short:'الفرق بين البيع الحقيقي والقرض المتخفي، بأمثلة بالأرقام.',
summary:'<p>المنتج الإسلامي الحقيقي فيه <b>تملك حقيقي</b> و<b>تحمّل مخاطرة</b>. لو المنتج بيضمن رأس مالك وعائد ثابت زي القرض بالظبط، والأصل مجرد ورق — يبقى لازم تسأل.</p>',
body:'<ol class="steps"><li><b>[[murabaha|المرابحة]]:</b> البنك يشتري السلعة فعلًا ويملكها ويقبضها، وبعدين يبيعها لك بثمن معلوم.</li><li><b>[[musharaka|المشاركة]]</b>: الربح بالاتفاق والخسارة بقدر الحصص.</li><li><b>[[fund|الصناديق]]</b>: شروطها من بوست القناة: عدم ضمان رأس المال، عدم ضمان ربح محدد، مشروعية النشاط، عدم الاستثمار في السندات وأذون الخزانة.</li><li><b>[[sukuk|الصكوك]]</b>: ملكية حصة في أصل، مش دين.</li><li><b>[[tawarruq|التورق المنظم]]</b>: مجمع الفقه الدولي منعه {{F06}}.</li></ol>',
examples:[{title:'مثال: مرابحة عربية vs قرض بفايدة',kind:'hypothetical',open:true,html:'<div class="table-wrap"><table class="calc"><thead><tr><th>البند</th><th>مرابحة (صحيحة الشروط)</th><th>قرض بفايدة</th></tr></thead><tbody><tr><td>البنك يملك العربية؟</td><td>أيوه، يشتريها ويقبضها</td><td>لأ، يديك فلوس</td></tr><tr><td>الثمن</td><td>600,000 ثابت (500,000 + ربح 100,000)</td><td>500,000 + فايدة</td></tr><tr><td>القسط على 48 شهر</td><td>600,000 ÷ 48 = 12,500</td><td>حسب سعر الفايدة</td></tr><tr><td>لو اتأخرت</td><td>الثمن مايزيدش كربح للبنك</td><td>فوايد تأخير</td></tr><tr><td>لو العربية اتدمرت قبل التسليم</td><td>على البنك (لأنه المالك)</td><td>عليك</td></tr></tbody></table></div><p>لو البنك ما اشتراش ولا ملك ولا تحمّل أي مخاطرة → الصورة بقت قرض بزيادة باسم مرابحة.</p>'},
{title:'مثال: صك إجارة vs سند',kind:'hypothetical',html:CALC([['قيمة الإصدار','1,000 صك × 1,000','1,000,000'],['إيجار الأصل السنوي','90,000'],['=عائد الصك','90,000 ÷ 1,000','90 جنيه (9%) — مرتبط بالإيجار'],['السند المقابل','1,000,000 بفايدة 9%','90 جنيه — دين ثابت مضمون']])+'<p>الرقم واحد، لكن مصدره مختلف: الصك = إيجار أصل إنت شريك فيه. السند = فايدة على قرض.</p>'}],
cases:['C09','C10'],
shariah:'<h3>الحكم المنقول</h3><ul><li>المرابحة للآمر بالشراء: جائزة إذا وقعت بعد تملك السلعة وقبضها، والوعد غير ملزم للطرفين {{F05}} {{F21}}.</li><li>الصكوك: معيار أيوفي 17 {{F24}} وقرار المجمع في الصكوك {{F07}}.</li><li>الشركة والمضاربة: لا يجوز ضمان رأس المال أو ربح محدد {{F22,F23}}.</li><li>التورق المنظم: غير جائز عند مجمع الفقه الدولي {{F06}}.</li></ul>',
dispute:'<p>فيه نقاش في تطبيقات عملية كتير: «الوعد الملزم» في المرابحة، وبعض هياكل الصكوك اللي بتضمن رأس المال بطرق غير مباشرة (زي تعهد الشراء بالقيمة الاسمية) — وده اللي ظهر في قضية دانة غاز.</p>',
risks:'<ul><li>التسمية «إسلامي» من غير هيئة رقابة شرعية حقيقية.</li><li>المنتج الإسلامي ممكن يخسر عادي — التوافق مش ضمان ربح.</li></ul>',
checklist:['الجهة اشترت الأصل وملكته فعلًا؟','فيه ضمان لرأس المال أو عائد ثابت في عقد مشاركة/مضاربة؟','فيه هيئة رقابة شرعية معلنة وتقاريرها منشورة؟','قريت نشرة الاكتتاب/العقد؟'],
todo:['لو بنك عرض عليك تمويل إسلامي، اطلب العقد واسأل: إمتى البنك بيملك السلعة؟','اقرا تحليل بوست «صناديق الاستثمار» في تحليل الرسائل.'],
known:['شروط المرابحة والصكوك والصناديق في المعايير.'],unknown:['تطبيق جهة معيّنة للشروط دي.'],
quiz:[
{q:'في المرابحة الصحيحة، البنك:',opts:['بيديك فلوس تشتري بيها','بيشتري السلعة ويملكها وبعدين يبيعها لك','بيضمن لك ربح'],a:1,why:'التملك قبل البيع هو الفرق الجوهري.'},
{q:'صندوق «إسلامي» بيضمن لك 12% سنويًا ورأس مالك. ده:',opts:['متوافق','فيه إشكال: ضمان الربح ورأس المال يخالف طبيعة المشاركة','أحسن صندوق'],a:1,why:'المستثمر في الصندوق شريك يتحمل الربح والخسارة.'},
{q:'التورق المنظم عند مجمع الفقه الدولي:',opts:['جائز','غير جائز','مستحب'],a:1,why:'قرار المجمع منعه.'}]},

/* ======================================================= 13 */
{id:'crypto-13',n:13,level:'متقدم',domain:'العملات الرقمية',updated:'2026-10-14',
title:'العملات الرقمية: الحكم الشرعي محل بحث، والقانون المصري واضح',
short:'بيتكوين والعملات المستقرة والستيكنج والإقراض — المخاطر والخلاف والوضع في مصر.',
summary:'<p>مجمع الفقه الدولي (2019) <b>ما حسمش</b> الحكم وأوصى بمزيد من البحث. دار الإفتاء المصرية أفتت بالمنع. فيه علماء وهيئات أجازوا بضوابط. وقانونيًا في مصر: قانون البنوك بيمنع إصدار أو تداول أو الترويج للعملات المشفرة من غير ترخيص البنك المركزي.</p>',
body:'<ol class="steps"><li><b>إيه هي؟</b> أرصدة رقمية على [[blockchain|بلوكتشين]] من غير بنك مركزي.</li><li><b>بتكسب منين؟</b> غالبًا من ارتفاع السعر بس. مفيش أرباح شركة وراها (باستثناء بعض الرموز).</li><li><b>[[stablecoin|العملات المستقرة]]:</b> «مستقرة» ≠ مضمونة.</li><li><b>[[staking|الستيكنج]]</b> و<b>[[lending|الإقراض]]</b> و<b>[[yieldfarming|زراعة العائد]]</b>: لازم تعرف العائد جاي منين.</li><li><b>المنصات:</b> لو فلوسك في منصة، إنت معرض لإفلاسها (FTX، Celsius).</li></ol>',
examples:[{title:'مثال: تقلب حاد',kind:'hypothetical',open:true,html:CALC([['اشتريت','10,000$'],['نزلت 60%','10,000 × 0.40','4,000$'],['=محتاج تكسب كام عشان ترجع','10,000 ÷ 4,000 − 1','+150%']])+'<p>انهيارات بالحجم ده حصلت فعلًا في سوق العملات الرقمية أكتر من مرة.</p>'},
{title:'مثال: «حساب عائد» 10% على عملاتك',kind:'hypothetical',html:'<p>حطيت 1 بيتكوين في منصة بتديك 10% سنويًا. لو المنصة <b>بتسلّف</b> عملاتك لغيرك وتديك عائد ثابت → ده قرض بزيادة مشروطة. ولو المنصة أفلست → ممكن تخسر الأصل نفسه.</p>'}],
cases:['C01','C05','C06'],
shariah:'<h3>الحكم المنقول</h3><ul><li>مجمع الفقه الإسلامي الدولي، قرار 237 (8/24) — نوفمبر 2019: قضايا مؤثرة في الحكم لا تزال محل نظر، والمجلس يوصي بمزيد من البحث {{F12}}.</li><li>دار الإفتاء المصرية: فتوى بعدم الجواز {{F60}}.</li><li>آراء بالجواز بضوابط {{F40}}.</li></ul><p>صاحب القناة نفسه قال إنه «لا يستطيع أن يقول حكمًا» ونقل قرار المجمع ونصح بعدم التسرع — وده موقف متسق مع المجمع.</p>',
dispute:'<p><b>محل خلاف معتبر</b>: هل هي مال متقوّم؟ هل تأخذ حكم النقود (فيشترط التقابض)؟ هل الغرر فيها كثير؟ وإلى جانب الحكم الأصلي، <b>المنتجات المبنية عليها</b> (رافعة، إقراض بعائد، عقود) ليها أحكامها الخاصة.</p>',
risks:'<ul><li>التقلب الشديد.</li><li>إفلاس المنصات والاختراقات.</li><li>القيود القانونية في مصر.</li><li>عمليات احتيال كتير بتستخدم اسم «كريبتو».</li></ul>',
checklist:['فاهم المشروع والعملة دي بتعمل إيه؟','العائد جاي منين؟','عارف الوضع القانوني في بلدي؟','قادر أتحمل خسارة 80% أو أكتر؟'],
todo:['اقرا حالة FTX وCelsius في الحالات الحقيقية.','لو حد عرض عليك «عائد ثابت على الكريبتو»، ارجع لمثال الإقراض.'],
known:['المجمع ما حسمش الحكم.','دار الإفتاء المصرية منعت.','القانون المصري بيشترط ترخيص.'],unknown:['هل المجامع هتصدر حكم نهائي — لسه.'],
quiz:[
{q:'قرار مجمع الفقه الدولي 237 في العملات الرقمية:',opts:['أباحها','حرّمها','أوصى بمزيد من البحث ولم يحسم'],a:2,why:'ده نص القرار.'},
{q:'منصة بتديك 10% ثابت على عملاتك لأنها بتسلّفها. الإشكال:',opts:['مفيش','قرض بزيادة مشروطة + خطر إفلاس المنصة','العملة نفسها'],a:1,why:'الزيادة المشروطة على القرض ربا، وفيه خطر الطرف المقابل.'},
{q:'في مصر، تداول العملات المشفرة من غير ترخيص البنك المركزي:',opts:['مسموح','ممنوع بنص قانون البنوك','مش متنظم'],a:1,why:'المادة 206 من قانون البنوك 194 لسنة 2020.'}]},

/* ======================================================= 14 */
{id:'zakat-14',n:14,level:'متوسط',domain:'الزكاة',updated:'2026-10-14',
title:'زكاة الأسهم: إزاي تحسبها؟',
short:'المتاجر غير المستثمر طويل الأجل — بأمثلة بالأرقام.',
summary:'<ul><li>لو <b>بتتاجر</b> في الأسهم (بتشتري عشان تبيع): تزكي <b>القيمة السوقية</b> يوم حولان الحول × 2.5%.</li><li>لو <b>مستثمر للأرباح</b> طويل الأجل: فيه تفصيل — تزكي نصيبك من الأموال الزكوية في الشركة، أو العائد حسب أقوال، لو الشركة نفسها مابتزكيش.</li></ul>',
body:'<ol class="steps"><li>حدد نيتك: متاجرة ولا اقتناء.</li><li>حدد يوم الحول (سنة هجرية من ملك النصاب).</li><li>اتأكد إن مالك بلغ النصاب (قيمة 85 جرام ذهب عيار 24 عند كثير من العلماء — والسعر بيتغير).</li><li>طبّق الطريقة المناسبة لنيتك.</li></ol>',
examples:[{title:'مثال 1: متاجر',kind:'hypothetical',open:true,html:CALC([['القيمة السوقية للمحفظة يوم الحول','80,000'],['+ كاش في حساب التداول','6,000'],['=الوعاء','80,000 + 6,000','86,000'],['=الزكاة','86,000 × 2.5%','2,150 جنيه']])},
{title:'مثال 2: مستثمر طويل (طريقة الجزء الزكوي)',kind:'hypothetical',html:'<p><b>الافتراض:</b> معاك أسهم بقيمة 100,000، والشركة الأصول الزكوية فيها (نقد + بضاعة + ذمم) = 40% من قيمتها، والشركة مابتخرجش زكاة.</p>'+CALC([['نصيبك من الأموال الزكوية','100,000 × 40%','40,000'],['=الزكاة','40,000 × 2.5%','1,000 جنيه']])+'<p>لو مش قادر تعرف النسبة دي، فيه أقوال تانية (زي تزكية الربح الموزع عند قبضه) — راجع المرجع.</p>'}],
shariah:'<h3>الحكم المنقول</h3><ul><li>مجمع الفقه الدولي — زكاة الأسهم في الشركات {{F14,F15}}.</li><li>معيار أيوفي للزكاة {{F27}}.</li></ul>',
dispute:'<p>فيه اختلاف في طريقة زكاة أسهم الاقتناء، وفي هل الشركة هي المكلفة أم المساهم. المهم: لو الشركة بتخرج الزكاة عن المساهمين، المساهم مايزكيش تاني نفس المال.</p>',
risks:'<ul><li>تنسى الكاش اللي في حساب السمسار.</li><li>تخلط بين التطهير والزكاة — دول حاجتين مختلفين.</li></ul>',
todo:['اكتب في ملاحظاتك تاريخ حولك ونيتك في كل سهم.','استشير متخصص لو محفظتك فيها أنواع مختلفة.'],
known:['معدل 2.5% في عروض التجارة.'],unknown:['النسبة الزكوية في كل شركة — محتاجة قوائمها.'],
quiz:[
{q:'متاجر محفظته يوم الحول 40,000. زكاته:',opts:['1,000','400','4,000'],a:0,why:'40,000 × 2.5% = 1,000.'},
{q:'التطهير والزكاة:',opts:['حاجة واحدة','مختلفين: التطهير تخلص من محرم، والزكاة فريضة على المال','التطهير بيغني عن الزكاة'],a:1,why:'التطهير مش عبادة بنية الصدقة، الزكاة فريضة.'},
{q:'لو الشركة بتخرج الزكاة عن المساهمين:',opts:['أزكي تاني نفس المال','مابزكيش نفس المال مرتين','أزكي الضعف'],a:1,why:'لا ثِنى في الصدقة.'}]},

/* ======================================================= 15 */
{id:'read-15',n:15,level:'متوسط',domain:'التحقق والتضليل',updated:'2026-10-14',
title:'إزاي تقرا أي رسالة استثمارية وتكشف التضليل بنفسك',
short:'الطريقة اللي اتحللت بيها رسائل القناة — عشان تطبقها على أي قناة تانية.',
summary:'<p>أي رسالة: (1) مين اللي كاتب ومصلحته إيه؟ (2) إيه الحقائق القابلة للتحقق وإيه الآراء؟ (3) الأرقام بتتحسب صح؟ (4) المصادر موجودة وبتقول نفس الكلام؟ (5) إيه الناقص؟</p>',
body:'<ol class="steps"><li><b>الأصل:</b> انقل النص وتاريخه ورابطه.</li><li><b>افصل</b> الحقيقة عن الرأي عن الوعد.</li><li><b>افتح المصادر بنفسك</b>: رقم القرار صح؟ النص بيقول كده فعلًا؟ (في <a href="#/warnings">علامات التحذير</a> مثال لرقم قرار مكتوب غلط.)</li><li><b>أعد الحسابات.</b></li><li><b>دوّر على التعميم:</b> «كل المشتقات حرام بقرار المجمع» — هل القرار قال «كل»؟</li><li><b>اعرف المصلحة:</b> القناة بتبيع خدمة؟ ده مش عيب، بس لازم تعرفه.</li><li><b>اتأكد من الترخيص</b> لو فيه توصيات أو إدارة أموال {{E22}} — ولو قناة بتطلب منك تحويل فلوس للاستثمار، شوف القائمة التحذيرية {{E17}}.</li></ol>',
examples:[{title:'علامات تحذير مشهورة',kind:'hypothetical',open:true,html:'<div class="table-wrap"><table><thead><tr><th>العلامة</th><th>مثال</th><th>ليه خطر؟</th></tr></thead><tbody><tr><td>ربح مضمون</td><td>«10% شهريًا مضمون»</td><td>مفيش استثمار حقيقي بيضمن ده</td></tr><tr><td>استعجال</td><td>«آخر فرصة! الأماكن محدودة»</td><td>بيمنعك تفكر وتتحقق</td></tr><tr><td>صور أرباح بس</td><td>سكرين شوت محفظة كسبانة</td><td>سهل تتزيف، ومحدش بيصور خسايره</td></tr><tr><td>«سري» أو «ماتشاركش»</td><td>«المحتوى ده للمشتركين بس»</td><td>ممكن يكون حماية حقوق (مشروع) أو منع للتحقق — حسب السياق</td></tr><tr><td>غياب سجل كامل</td><td>بيعرض الصفقات الناجحة بس</td><td>انحياز في الاختيار</td></tr><tr><td>منصة مش مرخصة</td><td>«سجل في المنصة دي برابط الإحالة»</td><td>عمولة إحالة + صعوبة استرداد الفلوس</td></tr></tbody></table></div>'}],
shariah:'<p>التثبت من الأخبار واجب: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِن جَاءَكُمْ فَاسِقٌ بِنَبَإٍ فَتَبَيَّنُوا﴾. ونسبة حكم لمجمع أو عالم من غير توثيق دقيق ممكن توقع الناس في خطأ — حتى لو النية كويسة.</p>',
risks:'<ul><li>الثقة في الشخص بدل التحقق من الكلام.</li><li>اعتبار عدد المتابعين دليل صحة.</li></ul>',
checklist:['عرفت الكاتب ومصلحته؟','فصلت الحقيقة عن الرأي؟','فتحت المصدر الأصلي بنفسي؟','أعدت الحسابات؟','دورت على السجل الكامل؟','اتأكدت من الترخيص؟'],
todo:['طبّق القايمة دي على 3 رسائل من أي قناة.','قارن تحليلك بتحليل الموقع في <a href="#/messages">تحليل الرسائل</a>.'],
known:['منهج التحليل.'],unknown:['نية أي كاتب — مابنحكمش عليها.'],
quiz:[
{q:'قناة فيها 100 ألف مشترك. ده دليل على إيه؟',opts:['إن كلامها صح','إنها مشهورة بس — مش دليل صحة','إنها مرخصة'],a:1,why:'الشهرة مش دليل.'},
{q:'لقيت رقم قرار مجمع في رسالة. أعمل إيه؟',opts:['أصدقه','أفتح موقع المجمع وأتأكد من الرقم والنص','أتجاهله'],a:1,why:'التحقق من المصدر الأصلي.'},
{q:'«الأرباح المتوقعة 50%» ده:',opts:['حقيقة','توقع/وعد — مش حقيقة','ضمان'],a:1,why:'أي رقم مستقبلي توقع.'}]},

/* ======================================================= 16 */
{id:'decide-16',n:16,level:'متقدم',domain:'اتخاذ القرار',updated:'2026-10-14',
title:'قبل أي قرار: قائمة التحقق الكاملة (المالية + الشرعية)',
short:'تجمع كل اللي اتعلمته في خطوات عملية — والنتيجة الصحيحة أحيانًا «لسه».',
summary:'<p>القرار الواعي = <b>فاهم</b> + <b>متحقق</b> + <b>قادر أتحمل الخسارة</b> + <b>الحكم الشرعي متفحوص على العقد الفعلي</b>. لو أي حاجة ناقصة: «محتاج تحقق أكتر» هي الإجابة الصحيحة.</p>',
body:'<p>القائمة دي مش «إشارة دخول». هي فلتر: لو الفرصة عدّت منها كلها، يبقى أقل حاجة إنت فاهم إنت داخل في إيه.</p><div class="callout risk"><div><b class="t">تذكير</b>المعاملة المتوافقة شرعيًا ممكن تخسر. والمنتج قليل المخاطرة ممكن يكون غير متوافق. الاتنين أسئلة منفصلة.</div></div>',
examples:[],
shariah:'<p>الأصل المباح ممكن يتحول لمعاملة ممنوعة بسبب <b>طريقة التمويل</b> (قرض ربوي) أو <b>طريقة التنفيذ</b> (بيع قبل القبض، CFD بدل التملك). والتقييم المبدئي هنا مش بديل عن سؤال عالم متخصص في فقه المعاملات المالية، خصوصًا قبل استثمار فلوس حقيقية.</p>',
checklist:[{group:'الفهم'},'فاهم الاستثمار ده بيحقق أرباحه إزاي؟','أعرف مين الطرف التاني في المعاملة؟','أنا بملك الأصل فعلًا ولا بتعامل على سعره بس؟',{group:'الشرع'},'فيه فوايد أو قروض أو رسوم مرتبطة بالتمويل؟','النشاط نفسه مباح؟','الحكم اتفحص على تفاصيل العقد الفعلي مش على الاسم؟','سألت متخصص لو فيه خلاف أو غموض؟',{group:'المال'},'أقدر أتحمل الخسارة دي من غير ما حياتي تتأثر؟','حسبت الرسوم والضرايب؟','الجهة مرخصة؟',{group:'الأدلة'},'فيه أدلة موثوقة على الادعاءات؟','فيه معلومات ناقصة تستلزم إني أوقف؟'],
todo:['اطبع قائمة التحقق دي (زر PDF فوق).','لو فيه أي «مش عارف» → النتيجة: «محتاج مزيد من التحقق» — وده قرار سليم.'],
known:['الأسئلة اللي لازم تتسأل.'],unknown:['ظروفك المالية الشخصية — إنت الوحيد اللي يعرفها.'],
quiz:[
{q:'منتج متوافق شرعيًا يبقى:',opts:['مضمون الربح','ممكن يخسر عادي','قليل المخاطرة دايمًا'],a:1,why:'التوافق الشرعي والمخاطرة المالية سؤالين منفصلين.'},
{q:'لو في سؤال إجابته «مش عارف»، القرار الصحيح:',opts:['أدخل بمبلغ صغير','محتاج مزيد من التحقق قبل أي قرار','أسأل القناة وأدخل'],a:1,why:'الوقوف عند الشك قرار سليم.'},
{q:'سهم مباح اشتريته بقرض ربوي من السمسار:',opts:['المعاملة سليمة لأن السهم مباح','التمويل الربوي أدخل إشكال في المعاملة','مفيش علاقة'],a:1,why:'طريقة التمويل بتأثر في الحكم.'}]}
];
